css:
:root {
  --background: #faf8f6;
  --foreground: #1c1412;
  --card: #ffffff;
  --card-foreground: #1c1412;
  --popover: #ffffff;
  --popover-foreground: #1c1412;
  --primary: #92400e;
  --primary-foreground: #ffffff;
  --secondary: #fdf4ef;
  --secondary-foreground: #6b3a1f;
  --muted: #f2eee9;
  --muted-foreground: #7a706a;
  --accent: #f5dcc8;
  --accent-foreground: #6b3a1f;
  --destructive: #c52525;
  --destructive-foreground: #ffffff;
  --border: #e3dbd4;
  --input: #e3dbd4;
  --ring: #92400e;
  --chart-1: #92400e;
  --chart-2: #b45309;
  --chart-3: #c2410c;
  --chart-4: #a16207;
  --chart-5: #854d0e;
  --sidebar: #f0ece7;
  --sidebar-foreground: #1c1412;
  --sidebar-primary: #92400e;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e8ddd1;
  --sidebar-accent-foreground: #6b3a1f;
  --sidebar-border: #e3dbd4;
  --sidebar-ring: #92400e;
  --font-sans: "IBM Plex Sans", "Inter", ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-serif: "IBM Plex Serif", "Georgia", ui-serif, serif;
  --font-mono: "IBM Plex Mono", "Fira Code", ui-monospace, monospace;
  --radius: 0.5rem;
  --shadow-color: #241005;
  --shadow-opacity: 0.06;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
}

.dark {
  --background: #0c0908;
  --foreground: #e3dad4;
  --card: #141110;
  --card-foreground: #e3dad4;
  --popover: #100d0c;
  --popover-foreground: #e3dad4;
  --primary: #c2956a;
  --primary-foreground: #1a0e04;
  --secondary: #1c1614;
  --secondary-foreground: #a39890;
  --muted: #1e1816;
  --muted-foreground: #7a706a;
  --accent: #2a1e14;
  --accent-foreground: #d4a574;
  --destructive: #ef4444;
  --destructive-foreground: #fef2f2;
  --border: #28211c;
  --input: #2a231d;
  --ring: #c2956a;
  --chart-1: #c2956a;
  --chart-2: #d97706;
  --chart-3: #e07a5f;
  --chart-4: #dda15e;
  --chart-5: #bc6c25;
  --sidebar: #0a0807;
  --sidebar-foreground: #d6ccc5;
  --sidebar-primary: #c2956a;
  --sidebar-primary-foreground: #1a0e04;
  --sidebar-accent: #221a12;
  --sidebar-accent-foreground: #d4a574;
  --sidebar-border: #221c18;
  --sidebar-ring: #c2956a;
  --font-sans: "IBM Plex Sans", "Inter", ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-serif: "IBM Plex Serif", "Georgia", ui-serif, serif;
  --font-mono: "IBM Plex Mono", "Fira Code", ui-monospace, monospace;
  --radius: 0.5rem;
  --shadow-color: #010000;
  --shadow-opacity: 0.4;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-font-sans: var(--font-sans);
  --color-font-serif: var(--font-serif);
  --color-font-mono: var(--font-mono);
  --color-radius: var(--radius);
  --color-shadow-color: var(--shadow-color);
  --color-shadow-opacity: var(--shadow-opacity);
  --color-shadow-blur: var(--shadow-blur);
  --color-shadow-spread: var(--shadow-spread);
  --color-shadow-offset-x: var(--shadow-offset-x);
  --color-shadow-offset-y: var(--shadow-offset-y);
  --color-letter-spacing: var(--letter-spacing);
  --color-spacing: var(--spacing);
}
